// The official Straft Studio accounts, in one place: the only list of social addresses in the app.
// The marks are from Simple Icons (CC0), each flattened to moves, lines and curves in a 24-point box,
// so the app needs neither an image file nor a dependency for them. The names and marks belong to
// their owners and only point to Straft Studio's own accounts.
import SwiftUI

public struct SocialLink: Equatable, Identifiable, Sendable {
    /// Stable, also in the accessibility identifier of the card.
    public let id: String
    public let name: String
    /// The account as the site writes it.
    public let handle: String
    public let url: String
    let mark: String

    /// What a screen reader says for the card.
    public var accessibilityLabel: String { "\(name), \(handle), opens in your browser" }

    /// The address as a URL, only when it passes `isOfficial`: nothing else is ever opened.
    public var openableURL: URL? { SocialLinks.isOfficial(url) ? URL(string: url) : nil }
}

