    /// Discord goes through the website's address, so the invite can change without an app update.
    private static let hosts: Set<String> = [
        "www.youtube.com", "www.facebook.com", "www.instagram.com", "x.com", "www.threads.com",
        "www.linkedin.com", "www.reddit.com", "straftstudio.com",
    ]

    /// https, one of the official sites, no user name or password, no port.
    public static func isOfficial(_ url: String?) -> Bool {
        guard let url, let u = URL(string: url), u.scheme == "https", u.user == nil, u.password == nil,
              u.port == nil, let host = u.host
        else { return false }
        return hosts.contains(host)
    }
}

/// A platform's mark, drawn from `SocialLink.mark` in the current text colour.
struct SocialMark: Shape {
    let commands: String

    func path(in rect: CGRect) -> Path {
        let scale = min(rect.width, rect.height) / 24
        let dx = rect.midX - 12 * scale, dy = rect.midY - 12 * scale
        var path = Path()
        let parts = commands.split(separator: " ")
        var i = parts.startIndex
        func point() -> CGPoint? {
            guard i + 1 < parts.endIndex, let x = Double(parts[i]), let y = Double(parts[i + 1]) else { return nil }
            i += 2
            return CGPoint(x: x * scale + dx, y: y * scale + dy)
        }
        while i < parts.endIndex {
            let command = parts[i]
            i += 1
            switch command {
            case "M": if let p = point() { path.move(to: p) }
            case "L": if let p = point() { path.addLine(to: p) }
            case "C":
                if let a = point(), let b = point(), let p = point() { path.addCurve(to: p, control1: a, control2: b) }
            case "Z": path.closeSubpath()
            default: return path
            }
        }
        return path
    }
}
